        const e = 1 - p.life, grow = Math.min(1, e / 0.3), L = p.r * (0.5 + 0.5 * grow), w = 30 * (1 - e * 0.8);
        ctx.save(); ctx.translate(p.x, p.y); ctx.rotate(p.ang);
        ctx.globalAlpha = Math.max(0, 1 - e * e) * 0.98;
